package br.com.sistemacardapio.pedido;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import br.com.sistemacardapio.tenant.TenantContext;
@RestController@RequestMapping("/api/dashboard")@PreAuthorize("hasRole('ADMIN_EMPRESA')")public class DashboardController{private final JdbcTemplate j;private final TenantContext t;public DashboardController(JdbcTemplate j,TenantContext t){this.j=j;this.t=t;}@GetMapping public Map<String,Object>obter(){UUID e=t.empresaIdObrigatoria();Map<String,Object>r=new LinkedHashMap<>();r.put("pedidosHoje",j.queryForObject("select count(*) from pedido where empresa_id=? and criado_em>=current_date",Long.class,e));r.put("produtosAtivos",j.queryForObject("select count(*) from produto where empresa_id=? and ativo=true",Long.class,e));r.put("categorias",j.queryForObject("select count(*) from categoria where empresa_id=? and ativa=true",Long.class,e));r.put("promocoesAtivas",j.queryForObject("select count(*) from promocao where empresa_id=? and ativa=true and inicio<=now() and fim>now()",Long.class,e));return r;}}
